<script type="module">
import * as THREE from 'three';

/* ---------- helpers ---------- */
let seed = 7;
function rnd() { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; }
function span(a, b) { return a + (b - a) * rnd(); }
function mesh(geo, mat, x, y, z) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  return m;
}

/* ---------- renderer / scene ---------- */
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xd89a72, 70, 340);

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 1200);
const camBase = new THREE.Vector3(0, 3.1, 36);
const camLook = new THREE.Vector3(0, 7.5, -60);

/* ---------- dusk sky (gradient dome + sun glow) ---------- */
const sunDir = new THREE.Vector3(-0.42, 0.10, -1).normalize();
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(600, 24, 16),
  new THREE.ShaderMaterial({
    side: THREE.BackSide, fog: false, depthWrite: false,
    uniforms: { uSunDir: { value: sunDir } },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }`,
    fragmentShader: `
      varying vec3 vDir;
      uniform vec3 uSunDir;
      void main() {
        float h = clamp(vDir.y * 1.2 + 0.12, 0.0, 1.0);
        vec3 low  = vec3(1.00, 0.58, 0.36);   // warm horizon
        vec3 mid  = vec3(0.86, 0.42, 0.50);   // rose band
        vec3 high = vec3(0.30, 0.26, 0.55);   // dusk indigo
        vec3 top  = vec3(0.12, 0.11, 0.30);   // deepening sky
        vec3 col = mix(low, mid, smoothstep(0.0, 0.30, h));
        col = mix(col, high, smoothstep(0.22, 0.55, h));
        col = mix(col, top, smoothstep(0.5, 1.0, h));
        float d = max(dot(normalize(vDir), uSunDir), 0.0);
        col += vec3(1.0, 0.72, 0.42) * (pow(d, 60.0) * 0.9 + pow(d, 8.0) * 0.22);
        gl_FragColor = vec4(col, 1.0);
      }`
  })
);
scene.add(sky);

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(0xb89ad2, 0x5a4a66, 1.25));
const sunLight = new THREE.DirectionalLight(0xffc08a, 2.0);
sunLight.position.copy(sunDir).multiplyScalar(100);
scene.add(sunLight);
const rim = new THREE.DirectionalLight(0xff8d9e, 0.45);
